function htLangSwitch(){let[l,setL]=n8.useState(window.htLang||"en");n8.useEffect(()=>{let f=e=>setL(e.detail);window.addEventListener("ht-lang",f);return()=>window.removeEventListener("ht-lang",f)},[]);return (0,y.jsx)("select",{className:"ht-lang",value:l,"aria-label":{en:"Language",it:"Lingua",es:"Idioma",de:"Sprache"}[l],"data-no-i18n":"1",onChange:e=>window.htSetLang(e.target.value),children:[["en","English"],["it","Italiano"],["es","Español"],["de","Deutsch"]].map(c=>(0,y.jsx)("option",{value:c[0],lang:c[0],children:c[1]},c[0]))})}
var LCA_UI={"basis": "Basis", "showinfo": "Show source and basis for this row", "infotitle": "Source and basis", "sources_lbl": "Sources:", "summary_lbl": "Basis of these values:", "jump": "Sources", "sec_title": "Sources & status of the data", "sec_intro": "Every figure in the tables above is marked by how well it is backed. Use the i next to a row for the detail. Where a source is named, it is listed here with what it was used for. Nothing is listed that was not actually used.", "legend": "What the labels mean", "refs_title": "Sources consulted", "used_for": "Used for:", "open": "Open source ↗", "not_itemised": "Not itemised here: the routing reference (sea, air and overland distances) combines published port-to-port distances where one was found with an independent route model, accurate to roughly ±10%. Sources 1 to 10 are cited as recorded in this tool; sources 11 onwards were checked online in October 2026, sometimes through the compilation named in the citation. Check the original publication before relying on a figure.", "edited_pre": "You changed at least one value in this row. The original basis was:", "custom_txt": "A row you added or renamed. Its basis is yours to document."},LCA_ST={"S": {"l": "Sourced", "d": "The value is taken from a named published source."}, "D": {"l": "Derived", "d": "Calculated from sourced values using the method stated in the note."}, "K": {"l": "Checked", "d": "Not taken directly from a source, but checked against a published figure that is close to it. The note gives the comparison."}, "M": {"l": "Partly sourced", "d": "Some columns come from a named source and the rest are assumed. The note says which."}, "A": {"l": "Assumed", "d": "An estimate chosen for this tool. No suitable source was found, so treat it as indicative."}, "E": {"l": "Edited", "d": "You changed this row from its default."}, "C": {"l": "Custom", "d": "A row you added or renamed."}},LCA_REFS=[{"id": 1, "s": "Quantis (2018)", "t": "Quantis (2018), Measuring Fashion", "u": "Stage split of an average garment's footprint (table 3) and the processing footprint (table 6).", "url": ""}, {"id": 2, "s": "UK DESNZ / DEFRA waste", "t": "UK DESNZ / DEFRA greenhouse gas conversion factors, clothing waste disposal (2024 and 2025 editions)", "u": "End-of-life factors for landfill, recycling and incineration, and the collection proxy used for resale (table 6).", "url": "https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2025"}, {"id": 3, "s": "Shen et al. (2010), EF 3.1", "t": "Shen, Worrell & Patel (2010); EU Environmental Footprint EF 3.1", "u": "Carbon factors for virgin and recycled polyester (table 2).", "url": ""}, {"id": 4, "s": "Wendin (2016)", "t": "Wendin (2016)", "u": "Carbon factor for recycled cotton (table 2).", "url": ""}, {"id": 5, "s": "Organic Cotton Accelerator", "t": "Organic Cotton Accelerator / South Pole (about 18,000 farms in India), as summarised by Carbonfact", "u": "Organic cotton saving and the upper end of the range for conventional cotton (table 2).", "url": "https://www.carbonfact.com/carbonfact-blogs/knowledge/carbon-footprint-cotton"}, {"id": 6, "s": "Higg MSI / MDPI", "t": "Higg MSI and published TENCEL life-cycle data (MDPI)", "u": "Carbon factors for viscose and lyocell (table 2).", "url": ""}, {"id": 7, "s": "nova-Institut", "t": "nova-Institut", "u": "Carbon factor for linen / flax (table 2).", "url": ""}, {"id": 8, "s": "14 wool LCAs", "t": "Median of 14 published wool LCAs (farm gate, greasy wool)", "u": "Carbon factor for wool (table 2).", "url": ""}, {"id": 9, "s": "Deep Dive step sources", "t": "Step-level sources for the LCA Deep Dive: Better Cotton farm LCA 2021 (summarised by Carbonfact), MDPI Sustainability (2020) on Patagonian lamb and wool, Textile Exchange polyester LCA (2026), Apparel Impact Institute / GEI thermal roadmap", "u": "How each stage is split into steps on the LCA Deep Dive page (indicative shares), and the note on electricity shares.", "url": ""}, {"id": 10, "s": "EU PEFCR (no value taken)", "t": "EU Product Environmental Footprint Category Rules for Apparel & Footwear (PEFCR)", "u": "Consulted for default end-of-life scenarios, but the figures could not be retrieved, so no value was taken from it.", "url": "https://www.carbonfact.com/hubfs/PEFCR%20Apparel%20%26%20Footwear.pdf"}, {"id": 11, "s": "UK DESNZ 2025 freight", "t": "UK DESNZ greenhouse gas conversion factors 2025: container ship and long-haul air freight, as tabulated by the New Zealand Ministry for the Environment", "u": "Ocean and air freight factors (table 4).", "url": "https://measuringemissionsguide.environment.govt.nz/8_freight.html"}, {"id": 12, "s": "GLEC Framework v3.2", "t": "GLEC Framework v3.2 (Smart Freight Centre, 2023), as compiled by Green Calculus", "u": "Road and rail freight factors (table 4).", "url": "https://greencalculus.com/data/business-travel-freight-logistics-emission-factors/"}, {"id": 13, "s": "UK DESNZ 2025 car", "t": "UK DESNZ greenhouse gas conversion factors 2025: average petrol car, as compiled by Green Calculus", "u": "Passenger car equivalent (table 5).", "url": "https://greencalculus.com/data/business-travel-freight-logistics-emission-factors/"}, {"id": 14, "s": "US EPA equivalencies", "t": "US EPA Greenhouse Gas Equivalencies Calculator: calculations and references (2024 update)", "u": "Smartphone charge equivalent (table 5).", "url": "https://www.epa.gov/energy/greenhouse-gas-equivalencies-calculator-calculations-and-references"}, {"id": 15, "s": "European Environment Agency", "t": "European Environment Agency figure for tree uptake, as quoted by One Tree Planted", "u": "Tree absorption equivalent (table 5).", "url": "https://onetreeplanted.org/blogs/stories/how-much-co2-does-tree-absorb"}, {"id": 16, "s": "Water Research Foundation (2016)", "t": "Water Research Foundation (2016), Residential End Uses of Water, version 2, as summarised by Wikipedia", "u": "Shower equivalent (table 5).", "url": "https://en.wikipedia.org/wiki/Residential_water_use_in_the_U.S._and_Canada"}, {"id": 17, "s": "EU JRC (2017)", "t": "EU Joint Research Centre (2017), follow-up of the preparatory study for the ecodesign and energy label of household washing machines", "u": "Real-life wash load, and the check on water per cycle (table 6).", "url": "https://publications.jrc.ec.europa.eu/repository/bitstream/JRC108583/jrc108583_wash_explanatory-notes_20171206_final_clean.pdf"}, {"id": 18, "s": "UKERC / Market Transformation Programme", "t": "UK Energy Research Centre data centre, washing machine energy per cycle (DEFRA Market Transformation Programme)", "u": "Check on energy per wash at different temperatures (table 6).", "url": "https://ukerc.rl.ac.uk/cgi-bin/dataDiscover.pl?Action=detail&dataid=e3fbc72a-6261-4184-a14b-68d470768f6d"}, {"id": 19, "s": "Ember (2026)", "t": "Ember, Global Electricity Review 2026 (2025 data)", "u": "World, EU, China and India electricity carbon intensity (table 6).", "url": "https://ember-energy.org/latest-insights/global-electricity-review-2026/major-countries-and-regions/"}, {"id": 20, "s": "Ember via Green Calculus", "t": "Ember country electricity carbon intensity (latest release), as compiled by Green Calculus", "u": "Electricity carbon intensity for the other origin countries (table 6).", "url": "https://greencalculus.com/data/grid-electricity-emission-factors/"}, {"id": 21, "s": "Hot or Cool Institute", "t": "Hot or Cool Institute, 1.5-Degree Lifestyles", "u": "Daily carbon budget (table 6).", "url": "https://hotorcool.org/1-5-degree-lifestyles/"}, {"id": 22, "s": "DESNZ 8% uplift", "t": "UK DESNZ methodology: 8% uplift on great-circle flight distances, as summarised by Green Calculus", "u": "Air routing uplift (table 6) and the air freight factor (table 4).", "url": "https://greencalculus.com/guides/carbon-footprint-of-flying/"}, {"id": 23, "s": "Chapagain et al. (2006)", "t": "Chapagain, Hoekstra, Savenije & Gautam (2006), The water footprint of cotton consumption, Ecological Economics 60(1)", "u": "Check on the water factor for conventional cotton (table 2).", "url": "https://doi.org/10.1016/j.ecolecon.2005.11.027"}, {"id": 24, "s": "Volgare et al. (2021)", "t": "Volgare et al. (2021), Washing load influences the microplastic release from polyester fabrics, Scientific Reports 11, which also reviews earlier studies", "u": "Check on microplastic shedding rates (table 2).", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC8484352"}, {"id": 25, "s": "EEA (2024)", "t": "European Environment Agency (2024), Management of used and waste textiles in Europe's circular economy", "u": "Context for the end-of-life mix (table 6).", "url": "https://www.eea.europa.eu/en/analysis/publications/management-of-used-and-waste-textiles-in-europes-circular-economy"}, {"id": 26, "s": "Draft PEFCR (2021)", "t": "Draft PEFCR for Apparel & Footwear (2021), as published by the European Environmental Bureau", "u": "Comparison for the default number of wears and wears per wash (table 6).", "url": "https://eeb.org/wp-content/uploads/2021/11/Draft-Product-Environmental-Footprint-Category-Rules-PEFCR-apparel-and-footwear.pdf"}, {"id": 27, "s": "EEA textiles module", "t": "European Environment Agency, Share of textile waste sent to incineration or landfill in the EU (circularity textiles module, 2022 data), citing ETC CE (2024)", "u": "Share of discarded textiles going to landfill or incineration (table 6).", "url": "https://www.eea.europa.eu/en/circularity/sectoral-modules/textiles/share-of-textile-waste-sent-to-incineration-or-landfill-in-the-eu"}, {"id": 28, "s": "EPREL tumble dryer", "t": "EU product database (EPREL), energy label data sheet for a 7 kg condenser tumble dryer, product 762333", "u": "Check on energy per tumble-dryer cycle (table 6).", "url": "https://eprel.ec.europa.eu/fiches/tumbledriers/Fiche_762333_EN.pdf"}, {"id": 29, "s": "ICAC pesticide facts", "t": "International Cotton Advisory Committee (ICAC), cotton pesticide facts: kg of active ingredient per hectare of cotton, 2006 to 2010", "u": "Country examples of pesticide use per hectare (table 6) and cotton’s past share of insecticides (Learn page).", "url": "https://icac.org/wp-content/uploads/2023/07/seep_pesticides_facts2.pdf"}, {"id": 30, "s": "ICAC Recorder (2024)", "t": "International Cotton Advisory Committee, The ICAC Recorder, June 2024: cotton and pesticides, 2018 to 2022 (pesticide data from Bayer Crop Science, area from FAOSTAT)", "u": "Pesticide use per hectare of cotton (table 6) and cotton’s share of world pesticide use (Learn page).", "url": "https://icac.org/wp-content/uploads/2024/11/e-cotton-Recorder-2-2024-V21.pdf"}, {"id": 31, "s": "ICAC (2026)", "t": "International Cotton Advisory Committee, K. Kranthi, presentation on cotton’s carbon footprint and pesticide use (January 2026)", "u": "Carbon factor for conventional cotton (table 2) and the check on pesticide use (table 6).", "url": "https://icac.org/wp-content/uploads/2026/01/4-Keshav-Kranthi.pdf"}, {"id": 32, "s": "ICAC 2024/25 outlook", "t": "International Cotton Advisory Committee, world cotton outlook for 2024/25 (32.85 million hectares, 25.22 million tonnes of lint, 768 kg per hectare), as reported by Alchempro", "u": "World average lint yield, used to turn per-hectare figures into per-kilogram figures (tables 2 and 6).", "url": "https://www.alchempro.com/news/cotton-news/global-cotton-production-consumption-set-to-rise-in-2024-25-icac-294218-newsdetails.htm"}, {"id": 33, "s": "Textile Exchange (2014)", "t": "Textile Exchange (2014), The Life Cycle Assessment of Organic Cotton Fiber (PE International), compared with Cotton Incorporated (2012) for conventional cotton", "u": "Checks on the carbon and water savings of organic cotton (table 2).", "url": "https://textileexchange.org/app/uploads/2025/01/the-life-cycle-assessment-of-organic-cotton-fiber_38172.pdf"}, {"id": 34, "s": "Hoekstra (2013)", "t": "Hoekstra (2013), global average water footprint of cotton lint (green, blue and grey water), as tabulated in Averink (2015), University of Twente", "u": "Water factor for organic cotton (table 2).", "url": "https://www.utwente.nl/en/et/wem/education/msc-thesis/2015/averink.pdf"}, {"id": 35, "s": "UK DESNZ well-to-tank", "t": "UK DESNZ / BEIS greenhouse gas conversion factors, well-to-tank factors for freight: container ship (2025 edition) and long-haul air freight (2024 edition)", "u": "Fuel-production part of the ocean and air freight factors (table 4).", "url": "https://www.gov.uk/government/publications/greenhouse-gas-reporting-conversion-factors-2025"}, {"id": 36, "s": "Ecobalyse", "t": "Ecobalyse, the French government’s calculator for the environmental cost of textiles, as used by ADEME’s Nos Gestes Climat: 100% cotton T-shirt of 150 g", "u": "Check on the processing footprint (table 6).", "url": "https://nosgestesclimat.fr/en/documentation/divers/textile/t%E2%80%91shirt/empreinte-carbone/hors-durabilit%C3%A9"}, {"id": 37, "s": "TENCEL Modal (2024)", "t": "Lenzing, TENCEL Modal fibre claim sheet (Higg MSI 3.8, October 2024)", "u": "Carbon factor for modal (table 2).", "url": "https://tencel.com/images/assets/claims/document/claim-proof-tencel-modal-fiber-snapshot-202410.pdf"}, {"id": 38, "s": "nova-Institut hemp (2015)", "t": "nova-Institut for the European Industrial Hemp Association, Carbon footprint of natural fibres (MultiHemp project)", "u": "Carbon factor for hemp (table 2).", "url": "https://eiha.org/media/2017/01/15-04-Carbon-Footprint-of-Natural-Fibres-nova1.pdf"}, {"id": 39, "s": "Refashion cashmere LCA (2026)", "t": "Refashion / ADEME, Cashmere LCA technical report (2026): nomadic and farmed cashmere in China and Mongolia", "u": "Carbon factor for cashmere (table 2).", "url": "https://pro.refashion.fr/en/app/uploads/2026/08/cashmere-lca-technical-report.pdf"}, {"id": 40, "s": "Textile Exchange cashmere (2026)", "t": "Textile Exchange, Cashmere LCA summary (2026)", "u": "Scope and method of the cashmere study, and the finding that the two farming systems do not differ significantly (table 2).", "url": "https://textileexchange.org/app/uploads/2026/07/Cashmere-LCA-Summary.pdf"}, {"id": 41, "s": "Fibre production table", "t": "Table of greenhouse gas emissions during textile fibre production citing Muthu (2015) and WRAP (2012), as reproduced in the Journal of Fiber Bioengineering and Informatics 11(1)", "u": "Carbon factor for acrylic (table 2).", "url": "https://doc.global-sci.org/uploads/Issue/JFBI/v11n1/111_1.pdf"}, {"id": 42, "s": "AMSilk fibre LCA (2024)", "t": "AMSilk, Fiber LCA 2024 (public version): ecoinvent 3.9 mulberry silk yarn, cradle to gate", "u": "Upper end of the range of published carbon figures for silk (table 2).", "url": "https://amsilk.com/app/uploads/2024-06-18_Fiber-LCA-2024_public-version.pdf"}, {"id": 43, "s": "Nepal fibre comparison", "t": "Comparative life cycle assessment of textile fibres in Nepal (Rural Handmade)", "u": "Lower end of the range of published carbon figures for silk (table 2).", "url": "https://ruralhandmade.com/blog/comparative-life-cycle-assessment-of-textile-fibres-in-nepal"}, {"id": 44, "s": "MWool recycled wool (2022)", "t": "Life cycle assessment of MWool recycled wool fibres, Prato, Italy (Resources 2022, 11(5), 41; reference year 2019)", "u": "Carbon factor for recycled wool (table 2).", "url": "https://www.mdpi.com/2079-9276/11/5/41"}, {"id": 45, "s": "Aquafil ECONYL polymer LCA", "t": "Aquafil, life cycle assessment summary for ECONYL regenerated nylon polymer (ISO 14040/44, verified by Studio Fieschi & soci; data from 2023 to 2024)", "u": "Carbon factor for recycled nylon (table 2).", "url": "https://www.aquafil.com/assets/uploads/LCA_Grafica_ECONYL%C2%AE_POLYMER.pdf"}, {"id": 46, "s": "Alpaca farm-gate study (Peru)", "t": "Carbon footprint of alpaca fibre and meat in the Peruvian Andes, cradle to farm gate (Springer, 2022, doi 10.1007/s11250-022-03271-y)", "u": "Carbon factor for alpaca (table 2).", "url": "https://link.springer.com/article/10.1007/s11250-022-03271-y"}, {"id": 47, "s": "PUCP alpaca LCA (2021)", "t": "Pontificia Universidad Católica del Perú, life cycle assessment of alpaca garments for PROMPERÚ (2021), as reported by Apparel Insider", "u": "Range check for alpaca: 45 to 109 kg CO2e per kg of fleece (table 2).", "url": "https://apparelinsider.com/lca-studies-paint-positive-picture-for-alpaca/"}, {"id": 48, "s": "UNFCCC animal fibres (2023)", "t": "UNFCCC Fashion Charter, report on animal fibres (June 2023)", "u": "Finding that no life-cycle study of mohair, angora or camel hair exists, and the warning that allocation changes animal-fibre results up to three times (table 2).", "url": "https://unfccc.int/sites/default/files/resource/230620%20BLS2304%20UCC%20FC%20report%20animal%20fibres%20v03.pdf"}],LCA_RULES=[{"k": "assumptions", "re": "^Pesticide use: conventional cotton", "s": "D", "t": "Derived from ICAC data: cotton receives on average about 3.6 kg of pesticide active ingredient per hectare, herbicides included (2018 to 2022), and the world harvest is about 768 kg of lint per hectare (2024/25). 3.6 divided by 0.768 gives about 4.7 g per kg of fibre, with all of it assigned to the lint rather than shared with the cottonseed. Countries differ a lot: older ICAC figures that leave out herbicides range from 0.6 kg per hectare in Turkey to 4.9 in Brazil. This counts the amount used, not how toxic it is.", "r": [30,31,32,29]}, {"k": "assumptions", "re": "^Pesticide use: organic cotton", "s": "A", "t": "Organic standards prohibit synthetic pesticides, so the value is zero. Natural-origin sprays (such as neem or Bt) can still be used and are not counted.", "r": []}, {"k": "assumptions", "re": "^Pesticide use: recycled cotton", "s": "A", "t": "Made from existing textile waste, so no farm pesticides are allocated to it. This is the same cut-off approach as for its carbon figure.", "r": []}, {"k": "archetypes", "re": ".*", "s": "A", "t": "Typical weight, fibre blend, origin country and freight mode chosen to represent each garment. These are modelling assumptions, not averages taken from a source.", "r": []}, {"k": "materials", "re": "^Virgin Cotton$", "s": "M", "t": "Carbon: about 2.0 kg CO2e per kg of lint, the world average used by the International Cotton Advisory Committee (ICAC, 2026, citing the Carbon Trust). ICAC’s per-hectare figure (1,692 kg CO2e, mostly from nitrogen fertiliser) divided by the world yield of 768 kg of lint per hectare gives a similar 2.2. Studies range from about 1.8 (Cotton Incorporated, global, 2012) to 2.7 (irrigated cotton in India, Organic Cotton Accelerator / South Pole). Water: Chapagain et al. (2006) give about 8,500 L/kg for cotton lint and about 9,400 L/kg for finished cotton textile, counting rain and irrigation water but not dilution water; 10,000 is a rounded upper figure. Microplastics: none, as cotton is not a plastic.", "r": [31, 32, 33, 5, 23]}, {"k": "materials", "re": "^Organic Cotton$", "s": "D", "t": "Carbon: the world-average cotton figure reduced by 37%, the saving the Organic Cotton Accelerator / South Pole study found for organic against conventional irrigated cotton in India (about 1.7 against 2.7 kg CO2e/kg). A global study by Textile Exchange (2014) found a larger saving, 46%, but its critical review did not verify that comparison. Water: rainwater kept and irrigation water cut by 91%, as Textile Exchange (2014) reports for organic cotton. With 5,163 L/kg of rainwater and 2,955 L/kg of irrigation water for cotton lint (Hoekstra, 2013), that is about two thirds of the conventional figure, so about 6,700. Part of the saving reflects where organic cotton is grown, since much of it is rain-fed. Microplastics: none, as cotton is not a plastic.", "r": [5, 33, 34]}, {"k": "materials", "re": "^Recycled Cotton$", "s": "M", "t": "Carbon: from Wendin (2016). Water: assumed; no source is recorded. Microplastics: none, as cotton is not a plastic.", "r": [4]}, {"k": "materials", "re": "Polyester", "s": "M", "t": "Carbon: from Shen et al. (2010) and the EU Environmental Footprint dataset (EF 3.1). Water: assumed; no source is recorded. Microplastic shedding: within the range reported by laboratory washing studies (roughly 175 to 4,800 microfibres per gram per wash); the exact value is assumed.", "r": [3, 24]}, {"k": "materials", "re": "^(Viscose|Tencel)", "s": "M", "t": "Carbon: from the Higg MSI and published TENCEL life-cycle data (MDPI). Water: assumed; no source is recorded. Microplastics: none, as cellulose fibres are not plastics.", "r": [6]}, {"k": "materials", "re": "^Linen", "s": "M", "t": "Carbon: from nova-Institut flax data. Water: assumed; no source is recorded. Microplastics: none, as flax is not a plastic.", "r": [7]}, {"k": "materials", "re": "^Virgin Wool$", "s": "M", "t": "Carbon: median of 14 published life-cycle assessments, measured at the farm gate for greasy wool. Water: assumed; no source is recorded. Microplastics: none, as wool is not a plastic.", "r": [8]}, {"k": "materials", "re": "^(Nylon|Elastane)", "s": "M", "t": "Carbon: from secondary sources, so lower confidence than the other fibres. Water: assumed; no source is recorded. Microplastic shedding: within the range reported by laboratory washing studies (roughly 175 to 4,800 microfibres per gram per wash); the exact value is assumed.", "r": [24]}, {"k": "materials", "re": "^Acrylic", "s": "M", "t": "Carbon: about 7.6 kg CO2e per kg of fibre, from a table of fibre-production emissions that cites Muthu (2015) and WRAP (2012), as reproduced in the Journal of Fiber Bioengineering and Informatics. It is a secondary source with no stated system boundary, so confidence is lower than for the other fibres; the same table gives polyester 5.4 and wool 20.8. Water: assumed; no source is recorded. Microplastic shedding: assumed to be higher than for polyester, within the range reported by laboratory washing studies (roughly 175 to 4,800 microfibres per gram per wash); the exact value is assumed.", "r": [41]}, {"k": "materials", "re": "^Modal$", "s": "M", "t": "Carbon: 2.84 kg CO2e per kg of TENCEL Modal fibre (Lenzing, Higg MSI 3.8, October 2024), rounded to 2.8. This is one producer’s figure, so modal made with a dirtier energy supply may be higher. Water: assumed; no source is recorded. Microplastics: none, as cellulose fibres are not plastics.", "r": [37]}, {"k": "materials", "re": "^Hemp$", "s": "M", "t": "Carbon: 835 kg CO2e per tonne of hemp fibre grown in the Netherlands and northern Germany with mineral fertiliser (682 with pig slurry), from the nova-Institut study for the European Industrial Hemp Association, rounded to 0.84 per kg. It covers growing and mechanical fibre separation up to the factory gate, with retting left out, so textile-grade fibre will be somewhat higher. The carbon the plant stores while growing (about 1.4 kg CO2 per kg) is not counted. Water: assumed, on the same basis as linen. Microplastics: none, as hemp is not a plastic.", "r": [38]}, {"k": "materials", "re": "^Cashmere$", "s": "M", "t": "Carbon: 155 (farmed) to 183 (nomadic grazing) kg CO2e per kg of clean, dehaired cashmere at the processing gate, from the Refashion / ADEME life-cycle study of China and Mongolia (2026, ISO 14044, excluding land-use change). 170 is the midpoint. Textile Exchange’s summary reports no significant difference in climate impact between the two systems. Soil carbon loss from grazing is not counted and is highly uncertain. Water: assumed, on the same basis as wool; the study reports water-scarcity-weighted use (46 to 83 m3 world-equivalent per kg), which is a different measure. Microplastics: none, as cashmere is not a plastic.", "r": [39, 40]}, {"k": "materials", "re": "^Silk$", "s": "A", "t": "Assumed. Published carbon figures for silk differ a lot: about 81 kg CO2e per kg in a Nepalese comparison that counts the whole life cycle, and about 149 for ecoinvent mulberry silk, cradle to gate, as quoted by AMSilk in 2024 (the unit is not stated there). We found no study with a clear boundary, so 80, the lower of the two, is indicative and probably an underestimate. Water is assumed. Microplastics: none, as silk is not a plastic.", "r": [42, 43]}, {"k": "materials", "re": "^Alpaca$", "s": "M", "t": "Carbon: 53 kg CO2e per kg of fibre at the farm gate for extensive alpaca farming in the Peruvian Andes, with the impact shared between fibre and meat by biophysical allocation (the same study gives 22.6 per kg live weight; economic and mass allocation give 24.0 and 29.5 per kg live weight). A Peruvian life-cycle study of alpaca garments found 45 to 109 kg CO2e per kg of fleece across regions. How the impact is shared can change animal-fibre results up to three times, so treat the value as indicative. Water: assumed, on the same basis as wool. Microplastics: none, as alpaca is not a plastic.", "r": [46, 47, 48]}, {"k": "materials", "re": "^Mohair$", "s": "A", "t": "Assumed. No life-cycle study of mohair was found (the 2023 UNFCCC Fashion Charter report on animal fibres found none), so the value for virgin wool is used as a stand-in. Mohair comes from Angora goats, so the real value could be quite different. Water is assumed, on the same basis as wool. Microplastics: none, as mohair is not a plastic.", "r": [48, 8]}, {"k": "materials", "re": "^Recycled Wool$", "s": "M", "t": "Carbon: 0.627 kg CO2e per kg of mechanically recycled wool fibre (MWool, Prato, Italy, reference year 2019), rounded to 0.6, from a cradle-to-gate study in which the textile waste carries no burden (the cut-off approach). The study’s scenarios range from 0.1 to 0.94. It also reports results with the EU Circular Footprint Formula, which share the burden of the virgin fibre and are much higher; the cut-off value is used here to match recycled cotton and recycled polyester. Water: assumed. Microplastics: none, as wool is not a plastic.", "r": [44]}, {"k": "materials", "re": "^Recycled Nylon$", "s": "M", "t": "Carbon: 1.69 kg CO2e per kg of ECONYL regenerated nylon polymer (Aquafil, ISO 14040/44, verified by Studio Fieschi & soci, data from 2023 to 2024), rounded to 1.7. It is cradle to gate for the polymer granules; spinning into yarn is not counted. Aquafil states a 74% reduction against its standard nylon, which implies about 6.5 for the virgin comparison, well below this tool’s 15.4 for nylon 6.6. Water: assumed. Microplastic shedding: assumed to match virgin nylon, within the range reported by laboratory washing studies (roughly 175 to 4,800 microfibres per gram per wash); the exact value is assumed.", "r": [45, 24]}, {"k": "phases", "re": ".*", "s": "D", "t": "Derived from Quantis, Measuring Fashion (2018): fibre 15%, yarn and fabric preparation 40%, dyeing and finishing 36%, assembly 7%. These add up to 98%, so they are scaled to 100%. The raw-materials share is replaced by your actual fibres; the other rows divide the processing footprint.", "r": [1]}, {"k": "transport", "re": "^Ocean", "s": "S", "t": "UK DESNZ factors for an average container ship: 0.0161 kg CO2e per tonne-km from burning the fuel plus 0.0037 from producing and delivering it (well-to-tank), about 0.020 in total. Counting fuel production puts sea freight on the same well-to-wheel basis as the road and rail factors from the GLEC Framework.", "r": [11, 35]}, {"k": "transport", "re": "^Air", "s": "D", "t": "Derived from UK DESNZ long-haul air freight factors: 0.531 kg CO2e per tonne-km from burning the fuel (2025, without radiative forcing) plus 0.135 from producing it (well-to-tank, 2024), about 0.67 in total, divided by the 8% routing uplift because this tool already adds that uplift to the flight distance. The GLEC Framework gives a similar 0.61 for long-haul freighter aircraft. Counting the extra warming from emissions at altitude (radiative forcing) would raise it by about half.", "r": [11, 35, 12, 22]}, {"k": "transport", "re": "^Road", "s": "S", "t": "GLEC Framework v3.2 factor for an articulated diesel truck of 18 to 27 tonnes. Well-to-wheel, so it includes fuel production; real values vary with truck size and load.", "r": [12]}, {"k": "transport", "re": "^Rail", "s": "S", "t": "GLEC Framework v3.2 factor for European diesel rail freight (0.0307 kg CO2e per tonne-km, well-to-wheel), rounded. Electric rail is lower, at about 0.011.", "r": [12]}, {"k": "equivalents", "re": "^Passenger Car$", "s": "S", "t": "UK DESNZ 2025 factor for an average petrol car (0.163 kg CO2e per km).", "r": [13]}, {"k": "equivalents", "re": "^Smartphone", "s": "S", "t": "US EPA greenhouse gas equivalencies (2024 update): 0.0124 kg CO2 per smartphone charged, based on the US electricity grid.", "r": [14]}, {"k": "equivalents", "re": "^Tree", "s": "S", "t": "About 22 kg CO2 per mature tree per year (0.0602 kg per day), the figure given by the European Environment Agency. The EEA does not cite a study for it, and real uptake varies a lot with species and age.", "r": [15]}, {"k": "equivalents", "re": "^Water Showers$", "s": "S", "t": "Water Research Foundation, Residential End Uses of Water (2016): the average shower uses 15.8 US gallons, about 60 litres.", "r": [16]}, {"k": "assumptions", "re": "^Wash load", "s": "S", "t": "EU JRC study for washing-machine ecodesign (2017): the real-life average load is about 3.4 kg per cycle for cotton programmes.", "r": [17]}, {"k": "assumptions", "re": "^Water per wash", "s": "K", "t": "JRC data suggest about 45 litres per cycle for machines sold in 2013. 50 litres is kept as a round, slightly conservative figure.", "r": [17]}, {"k": "assumptions", "re": "^Energy per wash", "s": "K", "t": "Data from the UK Market Transformation Programme show a 40 °C wash uses about 40% less energy than a 60 °C wash, in line with these values. The absolute values are assumed.", "r": [18]}, {"k": "assumptions", "re": "^Energy per tumble", "s": "K", "t": "Checked against one listed model: a 7 kg condenser tumble dryer is rated 4.21 kWh for a full standard cotton load, about 0.6 kWh per kg, which is close to this value (2 kWh for a 3.4 kg load, about 0.59 kWh per kg). Heat-pump dryers use much less and vented dryers usually more, so the real value depends on the machine.", "r": [28]}, {"k": "assumptions", "re": "^Grid carbon intensity", "s": "S", "t": "Average carbon intensity of EU electricity in 2025 (Ember: 210 g CO2e per kWh), used for your own washing and drying. Laundering outside Europe would usually be higher.", "r": [19]}, {"k": "assumptions", "re": "^Daily carbon budget", "s": "D", "t": "Derived from the Hot or Cool Institute's 1.5-degree lifestyle target of 2.5 t CO2e per person per year by 2030, divided by 365 (about 6.8 kg per day). Used only for context; it does not change the footprint.", "r": [21]}, {"k": "assumptions", "re": "^Air routing uplift", "s": "S", "t": "UK DESNZ adds 8% to great-circle flight distances to allow for indirect routing and holding patterns.", "r": [22]}, {"k": "assumptions", "re": "^Processing footprint", "s": "D", "t": "Derived: fibre production is taken as 15% of an average garment (Quantis, 2018), with a production-weighted average fibre of about 3.7 kg CO2e/kg. That gives about 21 kg CO2e/kg for the yarn-to-assembly stages. Independent estimates range from about 11 to 26. Check: France’s Ecobalyse calculator gives 4.78 kg CO2e for a 150 g cotton T-shirt made in Asia, counted up to the shop (about 32 kg per kg of garment); this tool gives about 30 kg per kg for the same stages with its default origin.", "r": [1, 36]}, {"k": "assumptions", "re": "^Origin grid reference", "s": "S", "t": "World average carbon intensity of electricity in 2025 (Ember Global Electricity Review 2026).", "r": [19]}, {"k": "assumptions", "re": "^Origin grid: Other country", "s": "A", "t": "Used only when the country of manufacture isn’t in the list: the world-average electricity carbon intensity (same as the origin grid reference). It is not a real country, so treat the result as less certain.", "r": [19]}, {"k": "assumptions", "re": "^Origin grid: (China|India)$", "s": "S", "t": "Ember Global Electricity Review 2026, 2025 data (life-cycle emissions).", "r": [19]}, {"k": "assumptions", "re": "^Origin grid", "s": "S", "t": "Ember data (latest release, life-cycle emissions), as compiled by Green Calculus. Real values change every year.", "r": [20]}, {"k": "assumptions", "re": "^Electricity share", "s": "A", "t": "Estimated share of each phase's energy that comes from electricity. An assumption. The Apparel Impact Institute notes that heat (mostly steam) dominates the energy used in wet processing, which is why that row is low.", "r": [9]}, {"k": "assumptions", "re": "^Uncertainty", "s": "A", "t": "A screening-level range based on judgement, not a measured confidence interval. The mill row is ±60% because the few published garment studies we could compare (one pair of jeans and two T-shirts) differ from the model by roughly -55% to +90%.", "r": []}, {"k": "assumptions", "re": "^Service life: default wears", "s": "A", "t": "An assumption. The draft EU PEFCR for apparel (2021) uses higher defaults: 45 uses for T-shirts, 70 for trousers and 85 for sweaters.", "r": [26]}, {"k": "assumptions", "re": "^Service life: wears per wash", "s": "K", "t": "Set to 2 uses per wash, the value the draft PEFCR uses in its illustrative shirt example. That is one example, not a measured average, so real habits vary.", "r": [26]}, {"k": "assumptions", "re": "^End of life: landfill", "s": "S", "t": "UK DESNZ / DEFRA conversion factor for clothing sent to landfill (496.7 kg CO2e per tonne in the 2024 edition and 496.8 in 2025).", "r": [2]}, {"k": "assumptions", "re": "^End of life: recycling", "s": "S", "t": "UK DESNZ / DEFRA 2024 conversion factor for clothing, closed-loop recycling (6.4 kg CO2e per tonne). It covers only transport to the recycling facility, with no credit for avoided virgin production.", "r": [2]}, {"k": "assumptions", "re": "^End of life: incineration", "s": "S", "t": "UK DESNZ / DEFRA 2024 conversion factor for clothing, combustion (6.4 kg CO2e per tonne). It covers only transport to the facility; the fossil carbon from synthetic fibres is added separately in the next row.", "r": [2]}, {"k": "assumptions", "re": "^End of life: fossil", "s": "D", "t": "Computed from carbon content: polyester (PET) is about 62.5% carbon by mass, so burning 1 kg releases about 0.625 × 44/12 ≈ 2.3 kg of CO2. Natural-fibre carbon is treated as biogenic and not counted.", "r": []}, {"k": "assumptions", "re": "^End of life: resale", "s": "D", "t": "Uses the same DESNZ / DEFRA collection and transport factor as recycling, as a proxy for collection and sorting. No credit is taken for a second owner.", "r": [2]}, {"k": "assumptions", "re": "^End-of-life mix", "s": "M", "t": "Landfill plus incineration is 73% and the remaining 27% is collected for reuse or recycling. The 73% is the EEA figure for discarded textiles in the EU in 2022, including textiles in mixed household waste (ETC CE estimate). The 27% counts collected textiles, which includes exports, so not all of it is actually reused. The EEA does not split the 73% between landfill and incineration, so 33% and 40% are assumed.", "r": [27, 25]}].map(x=>({...x,re:new RegExp(x.re,"i")}));
